using FinTrack.Shared.Kernel.Ids;

namespace FinTrack.Budget.Domain.Buckets;

/// <summary>
/// Identifies a bucket. Generated by the client for buckets the user creates (a version 7 UUID,
/// checked with <see cref="StronglyTypedId.FromClient{TId}"/>), by the server for <c>Unallocated</c>.
/// </summary>
public readonly record struct BucketId : IStronglyTypedId<BucketId>
{
    private BucketId(Guid value) => Value = value;

    /// <inheritdoc />
    public Guid Value { get; }

    /// <inheritdoc />
    public static BucketId From(Guid value) =>
        value == Guid.Empty ? throw new ArgumentException("A bucket identifier cannot be empty.", nameof(value)) : new BucketId(value);

    /// <summary>The identifier in the standard <c>D</c> format.</summary>
    public override string ToString() => Value.ToString();
}
